def check_polynomial(a, y1, y2):
    # Q(x) = x*(x-1)*(x-a) + (y2**2 - y1**2)*x + y1**2
    def Q(x):
        return x * (x - 1) * (x - a) + (y2**2 - y1**2) * x + y1**2

    # Check n = 0 and n = 1
    if not is_square(Q(0)) or not is_square(Q(1)):
        return False

    # Check a range of n
    for n in range(-100, 101):
        if n == 0 or n == 1:
            continue
        if is_square(Q(n)):
            return False
    return True

