def check_Q_y1y2(y1_sq, y2_sq, a, limit=1000):
    # Q(m) = m^3 + am^2 + (y2_sq - 1 - a)*m + y1_sq
    # Actually Q(0) = y1_sq.
    # Q(1) = 1 + a + (y2_sq - y1_sq - 1 - a)*1 + y1_sq = y2_sq.
    # Let's fix this.
    # Q(m) = m^3 + am^2 + bm + y1_sq
    # Q(1) = 1 + a + b + y1_sq = y2_sq => b = y2_sq - y1_sq - a - 1
    b = y2_sq - y1_sq - a - 1
    def Q(m):
        return m**3 + a*m**2 + b*m + y1_sq
    for m in range(-limit, limit + 1):
        if m == 0 or m == 1:
            continue
        if is_square(Q(m)):
            return m
    return None

